        sm.set_state_data(sm.idle, "count", 3)
        values = sm.state_data_values
        assert values == {"idle": {"count": 3, "items": [], "name": "i"}}
        # It's a snapshot: mutating it does not affect the live data.
        values["idle"]["count"] = 100
        assert sm.get_state_data(sm.idle)["count"] == 3

    async def test_changes_cleared_at_macrostep_boundary(self, sm_runner):
        class SM(ScopedMachine):
            def on_enter_c2(self, state_data):
                state_data["shared"] = "from-c2"

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "nxt")
        changes = sm.get_data_changes()
        assert [(c.state_id, c.key, c.old_value, c.new_value) for c in changes] == [
            ("p", "shared", "parent", "from-c2")
        ]
        # A new macrostep clears the previous records.
        await sm_runner.send(sm, "leave")
        assert sm.get_data_changes() == []


@pytest.mark.timeout(5)
class TestHistoryDataSnapshots:
    async def test_deep_history_restores_descendants(self, sm_runner):
        class SM(StateChart):
            class p(State.Compound, data={"pdata": 0}):
                h = HistoryState(type="deep")
                a = State(initial=True, data={"x": 1})
                b = State(data={"y": 2})
                ab = a.to(b)

            out = State()
            finish = State(final=True)
            leave = p.to(out)
            back = out.to(p.h)
            end = out.to(finish)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "ab")
        sm.set_state_data("b", "y", 99)
        sm.set_state_data("p", "pdata", 42)
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "back")
        # The remembered descendant is restored with its saved data...
        assert sm.get_state_data("b") == {"y": 99}
        # ...while the compound owning the history is re-entered with defaults.
        assert sm.get_state_data("p") == {"pdata": 0}

    async def test_shallow_history_restores_direct_children_only(self, sm_runner):
        class SM(StateChart):
            class p(State.Compound, data={"pdata": 0}):
                h = HistoryState()

                class inner(State.Compound, data={"idata": 0}):
                    leaf1 = State(initial=True, data={"l": 1})
                    leaf2 = State(data={"l": 2})
                    fwd = leaf1.to(leaf2)

            out = State()
            finish = State(final=True)
            leave = p.to(out)
            back = out.to(p.h)
            end = out.to(finish)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "fwd")
        sm.set_state_data("inner", "idata", 77)
        sm.set_state_data("leaf2", "l", 88)
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "back")
        # Direct child data restored...
        assert sm.get_state_data("inner") == {"idata": 77}
        # ...but deeper states re-enter from initial with fresh defaults.
        assert sm.get_state_data("leaf1") == {"l": 1}
        assert sm.get_state_data("leaf2") is None

    async def test_history_default_content_uses_fresh_defaults(self, sm_runner):
        class SM(StateChart):
            class p(State.Compound, data={"pdata": 0}):
                h = HistoryState()
                a = State(initial=True, data={"x": 1})
                b = State(data={"y": 2})
                ab = a.to(b)

            out = State(initial=True)
            finish = State(final=True)
            enter_via_history = out.to(p.h)
            leave = p.to(out)
            end = out.to(finish)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "enter_via_history")
        assert sm.get_state_data("a") == {"x": 1}
        assert sm.get_state_data("p") == {"pdata": 0}

    async def test_history_snapshot_updated_on_each_exit(self, sm_runner):
        class SM(StateChart):
            class p(State.Compound):
                h = HistoryState(type="deep")
                a = State(initial=True, data={"x": 1})
                b = State(data={"y": 2})
                ab = a.to(b)

            out = State(initial=True)
            finish = State(final=True)
            enter = out.to(p)
            back = out.to(p.h)
            leave = p.to(out)
            end = out.to(finish)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "enter")
        sm.set_state_data("a", "x", 10)
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "back")
        assert sm.get_state_data("a") == {"x": 10}
        # Second cycle: new snapshot overwrites the previous one.
        sm.set_state_data("a", "x", 20)
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "back")
        assert sm.get_state_data("a") == {"x": 20}


