    async def test_set_state_data_with_state_id_string(self, sm_runner):
        sm = await sm_runner.start(CounterMachine)
        sm.set_state_data("idle", "count", 7)
        assert sm.get_state_data("idle")["count"] == 7

    def test_set_state_data_unknown_state(self):
        sm = CounterMachine()
        with pytest.raises(InvalidDefinition, match="no state with id 'unknown'"):
            sm.set_state_data("unknown", "count", 1)

    def test_set_state_data_inactive_state(self):
        sm = CounterMachine()
        with pytest.raises(InvalidDefinition, match="not active"):
