    def test_set_state_data_undeclared_key(self):
        sm = CounterMachine()
        with pytest.raises(InvalidDefinition, match="does not declare a data variable"):
            sm.set_state_data(sm.idle, "undeclared", 1)

    def test_set_state_data_type_violation(self):
        sm = CounterMachine()
        with pytest.raises(InvalidDefinition, match="violates the type"):
            sm.set_state_data(sm.idle, "name", 42)

    def test_set_state_data_allows_none_with_type(self):
        sm = CounterMachine()
        sm.set_state_data(sm.idle, "name", None)
        assert sm.get_state_data(sm.idle)["name"] is None

