class TestPickle:
    def test_data_survives_pickle(self):
        sm = CounterMachine()
        sm.set_state_data(sm.idle, "count", 42)
        sm.get_state_data(sm.idle)["items"].append("x")
        restored = pickle.loads(pickle.dumps(sm))
        assert restored.get_state_data(restored.idle) == {
            "count": 42,
            "items": ["x"],
            "name": "i",
        }
        # Lifecycle still works after unpickling.
        restored.send("start")
        assert restored.get_state_data(restored.idle) is None
        assert restored.get_state_data(restored.running) == {"progress": 0.0}

    def test_unpickle_without_data_manager(self):
        """Instances pickled before the feature existed get a fresh manager."""
        sm = CounterMachine()
        state = sm.__getstate__()
        manager = state.pop("_data_manager")
        assert manager is not None
        sm2 = CounterMachine.__new__(CounterMachine)
        sm2.__setstate__(state)
        assert sm2.get_state_data(sm2.idle) == {"count": 0, "items": [], "name": "i"}


@pytest.mark.timeout(5)
class TestErrorRollback:
    async def test_failed_microstep_rolls_back_data(self, sm_runner):
        class SM(StateMachine):
            s1 = State(initial=True, data={"x": 1})
            s2 = State()
            go = s1.to(s2, on="boom")
            back = s2.to(s1)

            def boom(self):
                raise ValueError("explosion")

        sm = await sm_runner.start(SM)
        with pytest.raises(ValueError, match="explosion"):
            await sm_runner.send(sm, "go")
        # The configuration rollback keeps the data consistent: s1 is active again.
        assert "s1" in sm.configuration_values
        assert sm.get_state_data(sm.s1) == {"x": 1}
        assert sm.get_state_data(sm.s2) is None

    def test_type_violation_inside_callback_rolls_back(self):
        class SM(StateMachine):
            s1 = State(initial=True, data={"x": 1})
            s2 = State(data={"n": DataVar(type=int)})
            go = s1.to(s2)
            back = s2.to(s1)

            def on_enter_s2(self, state_data):
                state_data["n"] = "not-an-int"

        sm = SM()
        with pytest.raises(InvalidDefinition, match="violates the type"):
            sm.send("go")
        assert "s1" in sm.configuration_values
        assert sm.get_state_data(sm.s1) == {"x": 1}


class TestScxmlDataModel:
    def test_state_datamodel_parsed_as_python_literals(self):
        from statemachine.io.scxml.processor import SCXMLProcessor

        scxml = """
        <scxml xmlns="http://www.w3.org/2005/07/scxml" initial="s1" datamodel="python">
          <state id="s1">
            <datamodel>
              <data id="count" expr="0"/>
              <data id="items" expr="[1, 2]"/>
              <data id="label" expr="'hi'"/>
              <data id="empty"/>
              <data id="computed" expr="count + 1"/>
            </datamodel>
            <transition event="go" target="end"/>
          </state>
          <final id="end"/>
        </scxml>
        """
        processor = SCXMLProcessor()
        processor.parse_scxml("test_datamodel", scxml)
        sm = processor.start()
        # Literal exprs become state data defaults; `empty` defaults to None;
        # non-literal exprs are left to the runtime datamodel evaluator.
        assert sm.get_state_data("s1") == {"count": 0, "items": [1, 2], "label": "hi", "empty": None}
        sm.send("go")
        assert sm.get_state_data("s1") is None


